feed:
{{- /* River feed: mixed activity across the four content sections. */ -}}
{{- $eligible := where .Site.RegularPages "Section" "in" (slice "made" "playlists" "margins" "found") -}}
{{- $pages := first 30 ($eligible.ByDate.Reverse) -}}
{{- $self := .OutputFormats.Get "Atom" -}}
{{- $html := .OutputFormats.Get "HTML" -}}
{{- /* Hugo's smart-quote rendering emits HTML entities like ’
       which are valid HTML but NOT predefined in XML. Anywhere outside
       a CDATA section, we must decode HTML entities to Unicode and then
       re-escape for XML. The helper below does that round-trip. */ -}}
{{- $owner := .Site.Params.copyright_holder | default .Site.Title -}}
{{ printf (i18n "feedTitleAll" | default "%s") $owner | htmlUnescape | transform.XMLEscape }}
{{ with $html }}{{ .Permalink }}{{ else }}{{ .Permalink }}{{ end }}
{{ with index $pages 0 }}{{ .Lastmod.Format "2006-01-02T15:04:05Z07:00" }}{{ else }}{{ now.UTC.Format "2006-01-02T15:04:05Z07:00" }}{{ end }}
{{- with $self }}

{{- end }}
{{- with $html }}

{{- end }}
{{- with .Site.Params.description }}
{{ . | plainify | htmlUnescape | transform.XMLEscape }}
{{- end }}
Hugo
{{- range $pages }}

  {{ .Title | htmlUnescape | transform.XMLEscape }}

  {{ .Permalink }}
  {{ .Lastmod.Format "2006-01-02T15:04:05Z07:00" }}
  {{- with .Date }}
  {{ .Format "2006-01-02T15:04:05Z07:00" }}
  {{- end }}

    {{ with .Params.author }}{{ . | htmlUnescape | transform.XMLEscape }}{{ else }}{{ $.Site.Title | htmlUnescape | transform.XMLEscape }}{{ end }}

  {{- with .Params.description }}
  {{ . | plainify | htmlUnescape | transform.XMLEscape }}
  {{- else }}{{ with .Summary }}
  {{ . | plainify | htmlUnescape | transform.XMLEscape }}
  {{- end }}{{ end }}
  {{- /* Thumbnail: run originals through .Resize so the URL points at
         a file Hugo actually publishes (originals in /assets/ aren't
         copied unless transformed). External URLs pass through. */}}
  {{- $img := .Params.img | default .Params.image }}
  {{- $imgURL := "" }}
  {{- $imgType := "image/jpeg" }}
  {{- if $img }}
    {{- if hasPrefix $img "http" }}
      {{- $imgURL = $img }}
      {{- $ext := path.Ext $imgURL | lower }}
      {{- if eq $ext ".png" }}{{ $imgType = "image/png" }}{{ else if eq $ext ".webp" }}{{ $imgType = "image/webp" }}{{ else if eq $ext ".gif" }}{{ $imgType = "image/gif" }}{{ else if eq $ext ".avif" }}{{ $imgType = "image/avif" }}{{ end }}
    {{- else }}
      {{- $imgRes := resources.Get (strings.TrimPrefix "/" $img) }}
      {{- if $imgRes }}
        {{- $thumb := $imgRes.Resize "800x webp q85" }}
        {{- $imgURL = $thumb.Permalink }}
        {{- $imgType = "image/webp" }}
      {{- else }}
        {{- $imgURL = $img | absURL }}
      {{- end }}
    {{- end }}

  {{- end }}
  {{ if $imgURL }}<p><img src="{{ $imgURL }}" alt="{{ .Title }}" /></p>{{ end }}{{ .Content | safeHTML }}

{{- end }}
